const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const q = $input.first().json.query || {};
  const projectId = (q.id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'id query param requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const row = $input.first()?.json;
const sess = $('Decode JWT + Query').first().json;
if (!row || !row.project) {
  return [{ json: {
    data: {
      project_id: sess.project_id,
      project: null,
      iee: null,
      rcd: null,
      grants: null,
      telematic: null
    },
    meta: { request_id: sess.request_id, timestamp: new Date().toISOString() }
  }}];
}
return [{ json: {
  data: {
    project: row.project,
    iee: {
      approved: row.iee_approved || null,
      draft: row.iee_draft || null
    },
    rcd: {
      approved: row.rcd_approved || null,
      draft: row.rcd_draft || null
    },
    grants: row.grants_last || null,
    telematic: row.telematic_last || null
  },
  meta: {
    request_id: sess.request_id,
    timestamp: new Date().toISOString()
  }
}}];
